actions.script:
const result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters({datasetId:'otel_errors',
    queryString:'fingerprint:'+JSON.stringify(String(fingerprint)),from:from || 'now-7d',thru:thru || 'now',pageSize:1}).call()
errorGroup = result.hits && result.hits.length ? result.hits[0].body : {}
sampleTraces = errorGroup.sample_trace_ids || []
// The logs of the group: its exception type (else the start of its message) from a minute before it was first seen.
const millis = value => /^\d+$/.test(String(value)) ? Number(value) : Date.parse(String(value || ''))
const firstSeen = millis(errorGroup.first_seen), lastSeen = millis(errorGroup.last_seen)
logsFrom = Number.isFinite(firstSeen) ? new Date(firstSeen - 60000).toISOString() : from || 'now-7d'
logsThru = Number.isFinite(lastSeen) ? new Date(lastSeen + 60000).toISOString() : thru || 'now'
logsQueryString = errorGroup['exception.type'] ? 'exception.type:'+JSON.stringify(String(errorGroup['exception.type'])) :
    errorGroup.message ? 'body:'+JSON.stringify(String(errorGroup.message).slice(0,100)) : ''
